import {StafftoolsCustomProperties} from '@github-ui/stafftools-custom-properties-core'
import {useParams} from '@github-ui/react-router'
import {getDefinitionListPath} from '../paths'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {definitionsShowRoute} from './definitions-show-route'

export function DefinitionsShow() {
  const {data} = useRouteQuery(definitionsShowRoute, 'mainQuery')
  const {enterprise} = useParams()
  const {definition} = data

  return (
    <StafftoolsCustomProperties>
      <StafftoolsCustomProperties.NavigationHeader
        target="Organization"
        propertyName={definition.name}
        listPath={getDefinitionListPath(enterprise || '')}
      />
      <StafftoolsCustomProperties.DefinitionTextField label="Description" value={definition.description} />
      <StafftoolsCustomProperties.DefinitionTextField label="Value type" value={definition.valueType} />
      <StafftoolsCustomProperties.DefinitionBooleanField label="Required" value={definition.required} />
      <StafftoolsCustomProperties.DefinitionTextField label="Default value" value={definition.defaultValue} />
      <StafftoolsCustomProperties.DefinitionListField label="Allowed values" values={definition.allowedValues} />
    </StafftoolsCustomProperties>
  )
}

try{ DefinitionsShow.displayName ||= 'DefinitionsShow' } catch {}